wantSrcDir := mustEvalSymlinks(t, filepath.Join(worktreeDir, "src"))
if got := mustEvalSymlinks(t, filepath.Dir(srcAbs)); got != wantSrcDir {
	t.Errorf("AbsPath(src/main.go) parent = %q, want %q", got, wantSrcDir)
}

